"""Request handling for the API."""


_INVALID_AUTH_TOKEN_MESSAGE = "invalid auth token"


def _validate_request(auth_token):
    """Validate request credentials before any request data is processed.

    Missing credentials are rejected directly. All other credentials are
    delegated to the configured token validator.
    """
    if auth_token is None or not is_valid_token(auth_token):
        raise PermissionError(_INVALID_AUTH_TOKEN_MESSAGE)


def handle_request(data, auth_token):
    """Authenticate and process an incoming API request."""
    _validate_request(auth_token)
    return process(data)

